import {SWEEP_FIELDS,calibrationCoverage,stintDefaults} from './lab.mjs';
import {formatLap,signed} from './engine.mjs';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(id,label,value,min,max,step=1)=>`<label class="lab-input" for="${id}"><span>${label}</span><input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" required></label>`;
const options=Object.entries(SWEEP_FIELDS).map(([k,v])=>`<option value="${k}">${v.label} · ${v.unit}</option>`).join('');
const compoundOptions=['soft','medium','hard','intermediate','wet'].map(k=>`<option value="${k}">${k[0].toUpperCase()+k.slice(1)}</option>`).join('');
function download(name,contents,type='text/csv'){const url=URL.createObjectURL(new Blob([contents],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function initExperiments({db,getScenario,applyScenario,toast}){
 let activeWorker,activeType,revision=0,sweep,stint,stintCircuit='';
 const host=$('#experiments-view');
 host.innerHTML=`<div class="lab-intro"><div><p class="eyebrow">EXPERIMENTS / 2024 REFERENCE ERA</p><h2>Trade-offs, made visible.</h2><p>Explore a parameter landscape or project the next laps. Every point runs the same physical solver.</p></div><div class="lab-context" id="lab-context"></div></div><div class="lab-tabs" role="group" aria-label="Experiment type"><button class="active" data-lab-tab="sweeps" aria-pressed="true">01 / Parameter sweeps</button><button data-lab-tab="stints" aria-pressed="false">02 / Multi-lap stints</button></div>
 <section id="sweeps-panel"><div class="experiment-grid"><form id="sweep-form" class="panel experiment-controls"><p class="eyebrow">DEFINE THE EXPERIMENT</p><h3>One axis, or two.</h3><p class="small-note">All other inputs use your current Simulation scenario.</p><label class="lab-input" for="sweep-x"><span>Primary parameter</span><select id="sweep-x">${options}</select></label><div class="lab-input-pair">${number('sweep-x-min','From',5,0,110)}${number('sweep-x-max','To',45,0,110)}</div>${number('sweep-x-count','Samples',9,2,31)}<label class="lab-input" for="sweep-y"><span>Second axis</span><select id="sweep-y"><option value="">None · line plot</option>${options}</select></label><div id="sweep-y-fields" hidden><div class="lab-input-pair">${number('sweep-y-min','From',-2,-2,2)}${number('sweep-y-max','To',2,-2,2)}</div>${number('sweep-y-count','Samples per row',5,2,11)}</div><button class="button primary" id="sweep-run" type="submit">Run parameter sweep ↗</button><p class="small-note">Maximum 31 line points or 11 × 11 grid. Numerical sensitivity is modelled; response maps remain uncertain.</p></form><div class="panel experiment-result"><div class="panel-heading"><h3>The parameter landscape</h3><button class="text-button" id="sweep-export" disabled>Export CSV ↓</button></div><div class="experiment-status" id="sweep-status" role="status" aria-live="polite">Choose a range and run your first sweep.</div><div id="sweep-chart"></div><div id="sweep-detail"></div></div></div></section>
 <section id="stints-panel" hidden><div class="experiment-grid"><form id="stint-form" class="panel experiment-controls"><p class="eyebrow">PROJECT A STINT</p><h3>The tyre–fuel crossover.</h3><p class="small-note">Starting fuel and tyre age come from Simulation. Mean fuel is used within each flying lap.</p>${number('stint-laps','Laps',12,1,30)}${number('stint-burn','Assumed fuel use · kg/lap',2,.1,5,.001)}<p class="small-note" id="burn-explanation"></p>${number('stint-reserve','Fuel reserve · kg',1,0,5,.1)}<label class="lab-input" for="stint-comparison"><span>Compare starting compound</span><select id="stint-comparison">${compoundOptions}</select></label><details><summary>Optional tyre stop</summary>${number('stint-pit','Stop after lap · 0 = none',0,0,29)}${number('stint-pit-loss','Assumed pit loss · seconds',20,0,120,.1)}<label class="lab-input" for="stint-next"><span>New compound · both strategies</span><select id="stint-next">${compoundOptions}</select></label><p class="small-note">20 s is an editable illustration, not measured circuit data. No refuelling, pit-lane replay or cold-tyre transient.</p></details><button class="button primary" id="stint-run" type="submit">Project multi-lap stint ↗</button></form><div class="panel experiment-result"><div class="panel-heading"><h3>Stint pace & cumulative time</h3><button class="text-button" id="stint-export" disabled>Export CSV ↓</button></div><div id="stint-status" class="experiment-status" role="status" aria-live="polite">A projection, not a validated race forecast.</div><div id="stint-chart"></div><div id="stint-summary"></div><div class="table-scroll"><table><thead><tr><th>Lap</th><th>Fuel end</th><th>Tyre age / type</th><th>A pace</th><th>B pace</th><th>Δ cumulative</th></tr></thead><tbody id="stint-rows"></tbody></table></div><details class="stint-limits"><summary>Assumptions and projection limits</summary><ul id="stint-assumptions"><li>Fuel, wear, pit loss and energy initialization require explicit assumptions. Existing qualifying validation does not establish stint accuracy.</li></ul></details></div></div></section>`;
 const axis=(key)=>({field:$(`#sweep-${key}`).value,min:Number($(`#sweep-${key}-min`).value),max:Number($(`#sweep-${key}-max`).value),count:Number($(`#sweep-${key}-count`).value)});
 function resetAxis(key){const el=$(`#sweep-${key}`),field=SWEEP_FIELDS[el.value];if(!field)return;for(const end of ['min','max']){const input=$(`#sweep-${key}-${end}`);input.min=field.min;input.max=field.max;input.step=field.step;input.value=field[end];}const max=key==='y'||$('#sweep-y').value?11:31;const count=$(`#sweep-${key}-count`);count.max=max;let samples=Math.min(max,9);if(['tyreAge','wing'].includes(el.value)){samples=Math.min(max,field.max-field.min+1);while(samples>2&&!Number.isInteger((field.max-field.min)/(samples-1)))samples--;}count.value=samples;}
 $('#sweep-x').onchange=()=>resetAxis('x');$('#sweep-y').onchange=()=>{$('#sweep-y-fields').hidden=!$('#sweep-y').value;$('#sweep-x-count').max=$('#sweep-y').value?11:31;if(Number($('#sweep-x-count').value)>11&&$('#sweep-y').value)$('#sweep-x-count').value=11;resetAxis('y');};
 host.querySelectorAll('[data-lab-tab]').forEach(button=>button.onclick=()=>{const sweeps=button.dataset.labTab==='sweeps';$('#sweeps-panel').hidden=!sweeps;$('#stints-panel').hidden=sweeps;host.querySelectorAll('[data-lab-tab]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});});
 function run(type,settings){
  if(activeWorker&&activeType!==type)$(`#${activeType==='sweep'?'sweep':'stint'}-status`).textContent='Experiment cancelled when another run started. Your previous completed result is retained.';activeWorker?.terminate();activeType=type;const id=++revision;for(const key of ['sweep','stint'])$(`#${key}-run`).disabled=key===(type==='sweep'?'sweep':'stint');
  const target=type==='sweep'?'sweep':'stint';$(`#${target}-status`).textContent='Running complete solver laps…';$(`#${target}-status`).classList.remove('lab-error');
  try{activeWorker=new Worker('./lab-worker.mjs',{type:'module'});activeWorker.onmessage=e=>{if(e.data.id!==revision)return;activeWorker.terminate();activeWorker=null;$(`#${target}-run`).disabled=false;if(e.data.error){$(`#${target}-status`).textContent=e.data.error+((type==='sweep'?sweep:stint)?' The previous completed experiment remains visible.':'');$(`#${target}-status`).classList.add('lab-error');return;}if(type==='sweep'){sweep=e.data.result;renderSweep();}else{stint=e.data.result;renderStint();}};activeWorker.onerror=()=>{$(`#${target}-status`).textContent='The experiment could not run in the background. Reload and try again.';$(`#${target}-run`).disabled=false;activeWorker?.terminate();};activeWorker.postMessage({id,type,db,scenario:getScenario(),options:settings});}catch(error){$(`#${target}-status`).textContent=error.message;$(`#${target}-run`).disabled=false;}
 }
 $('#sweep-form').onsubmit=e=>{e.preventDefault();run('sweep',{x:axis('x'),y:$('#sweep-y').value?axis('y'):null});};
 $('#stint-form').onsubmit=e=>{e.preventDefault();run('stint',{laps:Number($('#stint-laps').value),burn:Number($('#stint-burn').value),reserve:Number($('#stint-reserve').value),comparisonCompound:$('#stint-comparison').value,pitAfter:Number($('#stint-pit').value),pitLoss:Number($('#stint-pit-loss').value),nextCompound:$('#stint-next').value});};
 function inspectPoint(index){const p=sweep.points[index];$('#sweep-detail').innerHTML=`<div class="sweep-inspect"><span class="eyebrow">SELECTED MODEL RUN</span><b>${formatLap(p.lapTime)}</b><span>${signed(p.delta)} s vs ${formatLap(sweep.reference)}</span><p>${SWEEP_FIELDS[sweep.x.field].label}: ${p.x} ${SWEEP_FIELDS[sweep.x.field].unit}${sweep.y?` · ${SWEEP_FIELDS[sweep.y.field].label}: ${p.y} ${SWEEP_FIELDS[sweep.y.field].unit}`:''}</p><div class="sweep-sectors">${p.sectorDeltas.map((v,i)=>`<span>S${i+1} <b>${signed(v)} s</b></span>`).join('')}</div><button id="sweep-apply" class="button quiet">Apply this point to Simulation ↗</button></div>`;$('#sweep-apply').onclick=()=>{applyScenario(p.scenario);toast('Sweep point loaded into Simulation.');};}
 function renderSweep(){
  const c=db.circuits.find(c=>c.id===sweep.baseline.circuit);$('#sweep-status').textContent=`${sweep.points.length} complete runs · ${c.name} · captured ${db.drivers.find(d=>d.id===sweep.baseline.driver).code} / ${sweep.baseline.compound} / ${sweep.baseline.fuel} kg baseline ${formatLap(sweep.reference)} · best model point ${formatLap(sweep.best.lapTime)}. Click a point to inspect sectors.`;$('#sweep-export').disabled=false;
  if(sweep.y){const min=Math.min(...sweep.points.map(p=>p.delta)),max=Math.max(...sweep.points.map(p=>p.delta));$('#sweep-chart').innerHTML=`<div class="heatmap-caption">Rows: ${SWEEP_FIELDS[sweep.y.field].label} · columns: ${SWEEP_FIELDS[sweep.x.field].label}</div><div class="heatmap-scroll"><div class="sweep-heatmap" style="grid-template-columns:5em repeat(${sweep.xs.length},minmax(4.1em,1fr))"><span></span>${sweep.xs.map(v=>`<b>${v}</b>`).join('')}${sweep.ys.map((v,row)=>`<b>${v}</b>${sweep.points.slice(row*sweep.xs.length,(row+1)*sweep.xs.length).map((p,col)=>`<button class="heatmap-cell" data-sweep-point="${row*sweep.xs.length+col}" style="--cell-intensity:${.08+.5*(p.delta-min)/(max-min||1)}" aria-label="${p.x}, ${p.y}, delta ${p.delta.toFixed(3)} seconds">${signed(p.delta)}<small>s</small></button>`).join('')}`).join('')}</div></div><p class="small-note">Stronger accent shading indicates slower model points. These are computed differences, not measured response maps.</p>`;
  }else{const ys=sweep.points.map(p=>p.delta),min=Math.min(...ys),max=Math.max(...ys),span=max-min||.01,coords=sweep.points.map((p,i)=>[60+i/(sweep.points.length-1)*670,200-(p.delta-min)/span*155]);$('#sweep-chart').innerHTML=`<svg class="lab-plot" viewBox="0 0 780 260" role="img" aria-label="Lap delta versus ${SWEEP_FIELDS[sweep.x.field].label}"><path class="plot-axis" d="M60 32V205H740"/><text x="4" y="48">${signed(max)} s</text><text x="4" y="204">${signed(min)} s</text><polyline class="plot-primary" fill="none" points="${coords.map(p=>p.join(',')).join(' ')}"/>${coords.map(([x,y],i)=>`<g class="plot-point" tabindex="0" role="button" data-sweep-point="${i}" aria-label="${sweep.points[i].x} ${SWEEP_FIELDS[sweep.x.field].unit}, delta ${signed(sweep.points[i].delta)} seconds"><circle cx="${x}" cy="${y}" r="10" fill="transparent"/><circle class="point-dot" cx="${x}" cy="${y}" r="4"/></g>`).join('')}<text x="60" y="232">${sweep.xs[0]}</text><text x="708" y="232">${sweep.xs.at(-1)}</text><text x="360" y="255">${SWEEP_FIELDS[sweep.x.field].label} · ${SWEEP_FIELDS[sweep.x.field].unit}</text></svg>`;}
  $('#sweep-chart').querySelectorAll('[data-sweep-point]').forEach(el=>{el.onclick=()=>inspectPoint(Number(el.dataset.sweepPoint));el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();el.click();}};});inspectPoint(sweep.points.indexOf(sweep.best));
 }
 function renderStint(){
  $('#stint-status').textContent=`${stint.options.laps} projected flying laps · captured ${stint.scenario.fuel} kg start · ${stint.scenario.compound} vs ${stint.options.comparisonCompound} · frozen conditions.`;$('#stint-export').disabled=false;
  const all=[...stint.a.rows,...stint.b.rows].map(x=>x.totalLap),min=Math.min(...all),max=Math.max(...all),span=max-min||1,path=rows=>rows.map((r,i)=>`${60+i/(rows.length-1||1)*670},${200-(r.totalLap-min)/span*155}`).join(' ');
  $('#stint-chart').innerHTML=`<div class="trace-key"><span><i class="orange"></i>A · ${stint.scenario.compound}</span><span><i class="cyan"></i>B · ${stint.options.comparisonCompound}</span></div><svg class="lab-plot" viewBox="0 0 780 250" role="img" aria-label="Modelled lap time over the stint"><path class="plot-axis" d="M60 30V205H740"/><text x="4" y="46">${max.toFixed(1)} s</text><text x="4" y="203">${min.toFixed(1)} s</text><polyline class="plot-primary" fill="none" points="${path(stint.a.rows)}"/><polyline class="plot-secondary" fill="none" points="${path(stint.b.rows)}"/><text x="60" y="234">Lap 1</text><text x="677" y="234">Lap ${stint.options.laps}</text></svg>`;
  $('#stint-summary').innerHTML=`<div class="stint-totals"><div><span>A / TOTAL</span><b>${formatLap(stint.a.total)}</b></div><div><span>B / TOTAL</span><b>${formatLap(stint.b.total)}</b></div><div><span>A MINUS B</span><b>${signed(stint.delta)} s</b></div></div><p class="small-note">Fuel mass falls while the tyre map loses grip. A tyre stop resets age and adds the entered pit loss; both strategies use the same stop. The crossover follows these assumptions.</p>`;
  $('#stint-rows').innerHTML=stint.a.rows.map((r,i)=>`<tr><td>${r.lap}${r.pitLoss?' · PIT':''}</td><td>${r.fuelEnd.toFixed(1)} kg</td><td>${r.tyreAge} / ${r.compound}</td><td>${r.totalLap.toFixed(2)} s</td><td>${stint.b.rows[i].totalLap.toFixed(2)} s</td><td>${signed(r.cumulative-stint.b.rows[i].cumulative)} s</td></tr>`).join('');$('#stint-assumptions').innerHTML=stint.assumptions.map(s=>`<li>${esc(s)}</li>`).join('');
 }
 $('#sweep-export').onclick=()=>download('laplab-parameter-sweep.csv','x,y,lap_time_s,delta_s,sector_1_delta_s,sector_2_delta_s,sector_3_delta_s\n'+sweep.points.map(p=>[p.x,p.y??'',p.lapTime,p.delta,...p.sectorDeltas].join(',')).join('\n'));
 $('#stint-export').onclick=()=>download('laplab-stint-projection.csv','strategy,lap,compound,tyre_age,fuel_start_kg,fuel_end_kg,lap_time_s,pit_loss_s,cumulative_s\n'+['a','b'].flatMap(k=>stint[k].rows.map(r=>[k.toUpperCase(),r.lap,r.compound,r.tyreAge,r.fuelStart,r.fuelEnd,r.lapTime,r.pitLoss,r.cumulative].join(','))).join('\n'));
 $('#coverage-button').onclick=()=>$('#coverage-dialog').showModal();
 return {update(s){
  const coverage=calibrationCoverage(db,s),c=db.circuits.find(c=>c.id===s.circuit);$('#coverage-label').textContent=coverage.status;$('#coverage-button').dataset.coverage=coverage.status.toLowerCase();
  $('#coverage-content').innerHTML=`<p class="coverage-domain">${coverage.status}</p><p>${coverage.matched} matched training laps · ${coverage.holdout} matched holdouts. Circuit held-out MAE ${coverage.mae.toFixed(2)} s; this does not validate all inputs.</p><div class="coverage-rows">${coverage.rows.map(r=>`<div><b><span class="coverage-dot ${r.supported?'covered':''}"></span>${r.label}</b><p>${esc(r.detail)}</p><small>${r.supported?'Reference available':'Outside reference coverage'}</small></div>`).join('')}</div><p class="small-note">${coverage.note}</p>`;
  $('#lab-context').innerHTML=`<span>WORKING SCENARIO</span><b>${c.name} / ${db.drivers.find(d=>d.id===s.driver).code}</b><small>${s.compound} · ${s.fuel} kg · ${s.tyreAge} laps old</small>`;
  if(stintCircuit!==s.circuit){stintCircuit=s.circuit;const defaults=stintDefaults(s);$('#stint-laps').value=defaults.laps;$('#stint-burn').value=defaults.burn;$('#stint-comparison').value=defaults.comparisonCompound;$('#stint-next').value=defaults.nextCompound;$('#burn-explanation').textContent=`Default assumed race budget: 110 kg ÷ ${ {silverstone:52,monza:53,monaco:78,bahrain:57}[s.circuit]} race laps. Budget average only; neither a 2024 fuel cap nor measured consumption. Set your own rate.`;}
 }};
}
